data = {
'Delta': (58048,61643,5995),
'United': (53717,57063,5096),
'Southwest': (26091,27483,321),
'American': (52788,54211,2614),
'Alaska': (10426,11735,570),
}
growth = {}
margin = {}
for k,(r23,r24,oi24) in data.items():
    growth[k] = (r24-r23)/r23*100
    margin[k] = oi24/r24*100

for k in data:
    print(k, f"growth={growth[k]:.2f}%", f"margin={margin[k]:.2f}%")

print("Growth rank:", sorted(growth.items(), key=lambda x:-x[1]))
print("Margin rank:", sorted(margin.items(), key=lambda x:-x[1]))

